playground.css:
body { font-family: system-ui, sans-serif; padding: 18px; background: #f8fafc; color: #0f172a; }
.demo { display: grid; gap: 14px; }
.box {
  width: 220px;
  padding: 16px;
  border: 6px solid #2563eb;
  background: #dbeafe;
  font-size: 0.84rem;
  font-weight: 600;
}
.border-box { box-sizing: border-box; }
.content-box { box-sizing: content-box; border-color: #ef4444; background: #fee2e2; }

.scroll-box {
  width: 280px;
  height: 90px;
  padding: 10px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  background: #fff;
  font-size: 0.85rem;
  overflow: auto;
}
